"""Record actual same-agent prose review and selected source witnesses, not universal atom scores."""
from pathlib import Path
import json,hashlib,datetime
P=Path(__file__).resolve().parent
R=P/'original-public-chapter-body-review-v1'
SOURCES=[P/name for name in ['original-faq-source-reacquisition-v1','original-faq-expansion-sources-v1','original-faq-remaining-public-sources-v1']]
def source(family,path):
 found=[]
 for base in SOURCES:
  for f in (base/family).rglob(Path(path).name):
   if f.is_file() and f.as_posix().endswith('/'+path):found.append(f)
 assert found,(family,path)
 assert len({hashlib.sha256(f.read_bytes()).hexdigest() for f in found})==1
 return found[0]
def witness(family,path,a,b,interpretation):
 f=source(family,path);lines=f.read_text().splitlines();assert 1<=a<=b<=len(lines)
 return {'source_snapshot':str(f),'source_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'source_path':path,'source_lines':[a,b],'exact_source_evidence':'\n'.join(lines[a-1:b]),'reviewed_interpretation':interpretation,'source_only':True}
def record(topic,family,observations,spans,captures,findings=None,procedural_pending=None):
 findings=findings or [];procedural_pending=procedural_pending or [];q=R/topic
 if (q/'body-semantic-review-v1.json').exists():
  print(topic,'PRESERVED_EXISTING_REVIEW_NOT_REWRITTEN');return
 docs=[]
 for lang in ['en','pt-br']:
  f=q/(lang+'.candidate.txt');docs.append({'language':lang,'path':str(f),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'read_in_full':True})
 source_rows=[witness(family,*entry) for entry in spans]
 capture_rows=[]
 for name in captures:
  f=P/'original-public-chapter-provenance-captures-v1'/name/'raw-response.json';capture_rows.append({'id':name,'raw_response':str(f),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'read_model_content_in_full':True,'origin':'original-public-chapter-provenance-capture-results-v3.json'})
 dims=json.loads((P/'acceptance-protocol-v2.json').read_text())['document_level']['dimensions'];scores={d:2 for d in dims}
 if findings:
  scores['factual correctness']=0 if any(x.get('verdict')=='CONTRADICTED' for x in findings) else 1
 if procedural_pending:scores['factual correctness']=min(scores['factual correctness'],1);scores['explicit limitations']=1
 result={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'topic':topic,'family':family,'scope':'Full actual EN/PT prose read; selected source witnesses and historical response claims checked. Qualitative whole-prose review, not exhaustive independently atomized precision. No unchanged old semantic score overwritten.','documents':docs,'selected_review_observations':observations,'source_witnesses':source_rows,'historical_captures_reviewed':capture_rows,'new_findings':findings,'procedural_provenance_pending':procedural_pending,'dimension_scores':scores,'complete_document_outcome':'REVISE_CURRENT_PROSE_FINDINGS' if findings else ('INCOMPLETE_PROCEDURAL_REVIEW' if procedural_pending else 'PASS_RESEARCH_REVIEW_SOURCE_ONLY'),'complete_document_accepted':not findings and not procedural_pending,'EN_PT_source_contract_parity':'No additional material source-contract divergence found in full bilingual body reading; specific procedural findings apply to both unless stated','no_upstream_execution':True,'reviewer':'Same campaign agent; not independent owner or human certification','owner_approved':False,'training_gold':False,'training_use_approved':False,'optimizer_updates':0}
 with (q/'body-semantic-review-v1.json').open('x') as f:json.dump(result,f,indent=2,ensure_ascii=False);f.write('\n')
 print(topic,result['complete_document_outcome'])
